List<BorderPublishedPrimitive> selbrumeTwoTierV4PublishedPrimitives() =>
    List<BorderPublishedPrimitive>.unmodifiable(
      <BorderPublishedPrimitive>[
        for (var index = 0; index < _selbrumeTwoTierV4Assets.length; index += 1)
          _selbrumeTwoTierV4Assets[index].toPrimitive(index),
      ],
    );

/// Exact 22 px face-neck anchors used by the Task 11 resolver QA pack.
///
/// The alpha masks stay identical to V4. Only the authored anchors change, so
/// tests exercise the real two-level silhouette without depending on Desktop
/// or `/tmp` project files.
List<BorderPublishedPrimitive> selbrumeTwoTierNeckPublishedPrimitives() =>
    List<BorderPublishedPrimitive>.unmodifiable(
      selbrumeTwoTierV4PublishedPrimitives().map((primitive) {
        final anchor = _selbrumeTwoTierNeckAnchor(primitive);
        final metrics = primitive.publishedMetrics;
        return BorderPublishedPrimitive(
          id: primitive.id,
          sourceElementId: primitive.sourceElementId,
          visualSnapshotId: primitive.visualSnapshotId,
          role: primitive.role,
          authoredOrientation: primitive.authoredOrientation,
          weight: primitive.weight,
          anchorPx: anchor,
          transforms: primitive.transforms,
          publishedMetrics: BorderPrimitiveAssetMetrics(
            assetFingerprint: metrics.assetFingerprint,
            pixelSize: metrics.pixelSize,
            opaqueBounds: metrics.opaqueBounds,
            defaultAnchorPx: anchor,
            occupancyMaskRle: metrics.occupancyMaskRle,
          ),
        );
      }),
    );

List<BorderVisualSnapshot> selbrumeTwoTierV4Snapshots(
  List<BorderPublishedPrimitive> primitives,
) =>
    List<BorderVisualSnapshot>.unmodifiable(
      <BorderVisualSnapshot>[
        for (final primitive in primitives)
          BorderVisualSnapshot(
            id: primitive.visualSnapshotId,
            contentFingerprint: primitive.visualSnapshotId.substring(
              'border-snapshot-sha256:'.length,
            ),
            frames: <BorderVisualFrameSnapshot>[
              BorderVisualFrameSnapshot(
                relativeAssetPath:
                    'assets/borders/snapshots/${primitive.id}.png',
                sourceRectPx: BorderPixelRect(
                  x: 0,
                  y: 0,
                  width: selbrumeTwoTierV4TileSize.width,
                  height: selbrumeTwoTierV4TileSize.height,
                ),
                durationMs: 100,
              ),
            ],
          ),
      ],
    );

BorderBlueprintRevision selbrumeTwoTierV4Revision(
  List<BorderPublishedPrimitive> primitives,
) =>
    BorderBlueprintRevision(
      revision: 1,
      definition: BorderBlueprintPublishedDefinition(
        name: 'Falaises Selbrume — deux étages',
        previewSeed: BorderSignedInt64.fromInt(240420260718),
        template: BorderBlueprintTemplate.stoneChainLine,
        primitives: primitives,
        defaults: BorderGenerationParams(
          irregularityPermille: 180,
          detailDensityPermille: 0,
          variationPermille: 1000,
          maxOverlapPx: 8,
          gapTolerancePx: 0,
          depthRows: 2,
          allowAutoRotation: false,
        ),
        sortOrder: 3,
      ),
    );

BorderResolutionRequest selbrumeTwoTierV4Request({
  required String featureId,
  required BorderStrokeGeometry geometry,
  BorderLineSide lineSide = BorderLineSide.primary,
  GridSize mapSize = const GridSize(width: 16, height: 12),
}) {
  final primitives = selbrumeTwoTierV4PublishedPrimitives();
  return BorderResolutionRequest(
